          "可先用短句列出问题页、动作页、条件页和下一步页，不把这些角色当作固定张数要求。一个复杂动作可能需要更多解释，一项简单说明也不必为了凑轮播长度增加空页。\n\n每页最好推进一个实际问题。开头提出的疑问应在后面得到回应，限制条件应靠近相关事实，而不是全部藏到最后。如果只看某一页，会不会误以为产品包含未附送的配件，也需要检查。\n\n页序是编辑选择，不是效果公式。它让创作者和品牌知道哪些信息可以合并、哪些不能省略，也有助于讨论新增页面是否真有用途。重复同一句利益点，并不等于进一步解释。",
          "Start with short role statements such as question, action, condition and next step. These are not a required page count. A complex action may need more explanation, while a simple one need not acquire empty pages to make the carousel longer.\n\nEach page should advance a practical question. Answer the opening question later, and place limitations near the relevant fact instead of hiding all conditions at the end. Check whether a person seeing one page alone might think an accessory is included when it is not.\n\nSequence is an editorial choice, not a performance formula. It tells both parties which information can be combined and which should remain visible, and helps assess whether another page has a purpose. Repeating a benefit is not necessarily additional explanation. A useful plan should make it possible to explain why every page exists before time is spent refining its decoration, transitions or typography."
