    "answer": [
      "多团队跟踪 Instagram 粉丝，应共用一个有来源的汇总记录：分别保留计数观察、已确认项目事件、待核实信息和编辑解释。指定谁采集、谁确认事件、谁维护当前报告；晚到资料用补充或更正处理，不悄悄覆盖原记录。粉丝变化与活动同期发生，不等于已证实归因。只分享与合作有关且适当的汇总信息，不把这项工作变成私人粉丝身份监控，也不承诺任何工具能还原全部历史。",
      "To track Instagram followers across teams, use one sourced aggregate record that distinguishes observations, confirmed campaign events, unverified information and interpretation. Assign collection, event confirmation and current-report ownership. Handle late evidence through additions or corrections rather than silently overwriting originals. A change occurring alongside a campaign does not establish attribution. Share only appropriate, task-related aggregates, without private follower surveillance or a promise that a tool can reconstruct all history."
    ],
