          "Unavailable independent evidence does not prove every sentence false. An unreadable page does not establish concealment, and an unusual count does not establish a creator’s participation.\n\nState accurately that a promise cannot be confirmed from current information and is unsuitable as support for a brand conclusion. If a verifiable conflict exists, identify its specific object and scope rather than extend it to every person or activity.\n\nThat wording does not prevent caution. The team can decline an unnecessary purchase, withhold access and avoid unsupported figures without permanently labeling a person. Review strength should match the evidence. Preserve facts, reasonable questions and unknown states separately, updating them when new information arrives. A bounded decision is useful precisely because it does not require a total verdict: the brand can decide the offer is unnecessary for its campaign while acknowledging that this review did not investigate every aspect of the provider or determine the origin of each interaction."
