          "The collaboration identity-map guide separates people, accounts and business contacts. A large-team proposal should likewise preserve unconfirmed matters rather than turn internal hopes into external commitments.\n\nThe handoff identifies current version, factual owner, production scope, appearance arrangements and release conditions. Record an initial reply as an initial reply. If an alternative is agreed, update its accurate name rather than retain wording that now misleads.\n\nScale information is background, not a substitute for confirming work. A recipient should know whom to ask next, which information is missing and which decisions cannot yet be executed. Accurate records prevent an unfinished contact from becoming a confirmed top-creator partnership in another proposal. They also make a changed arrangement reviewable: someone can compare the confirmed role with the original need and decide whether it still serves the campaign, instead of being guided by the familiar creator name alone."
